using Planner.Core;
using Planner.Data;
using System.Net;
using System.Text;
using System.Text.Json;
static class ConversationTests
{
 static void Equal<T>(T want,T got){if(!Equals(want,got))throw new Exception($"expected {want}, got {got}");}
 static Type Find(string name)=>typeof(PlannerState).Assembly.GetType("Planner.Core."+name)??typeof(SqliteStore).Assembly.GetType("Planner.Data."+name)??throw new Exception(name+" behavior missing");
 static dynamic New(string name,params object[] args)=>Activator.CreateInstance(Find(name),args)!;
 static dynamic Static(string name,string method,params object[] args)=>Find(name).GetMethod(method)!.Invoke(null,args)!;
 static void Reject(Action action){try{action();}catch(Exception e)when(e is ArgumentException or InvalidOperationException or System.Reflection.TargetInvocationException or OperationCanceledException){return;}throw new Exception("expected rejection");}
 static string Ready=>"{\"message\":\"信息已完整，请核对。\",\"summary\":\"明天参观南京博物院两小时\",\"missing\":[],\"ready\":true,\"events\":[{\"day\":\"2026-10-29\",\"title\":\"参观\",\"location\":\"南京博物院\",\"duration\":120}]}";
 static PlannerState State(){var s=new PlannerState();s.Tables.Add(new(){Id="t",Name="个人"});return s;}
 static PlannerState Added(PlannerState s)=>ChangeService.Apply(s,[new(){Activity=new(){Id="generated",TableId="t",Title="生成事项",StartAt=new(2026,10,29,10,0,0),EndAt=new(2026,10,29,11,0,0)}}],s.Revision);
 public static void Register(Action<string,Action> test)
 {
  test("conversation drafts stay isolated by branch and survive reopening",()=>{string dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());try{var store=new ConversationStore(dir);var c=new GuidedConversation();string first=c.ActiveBranchId;c.Drafts[first]="未发送的博物馆安排";var second=c.NewBranch();c.Drafts[second.Id]="工作安排草稿";store.Save(c);var read=store.Load();Equal("未发送的博物馆安排",read.Drafts[first]);Equal("工作安排草稿",read.Drafts[second.Id]);Equal(0,read.Branches.Sum(b=>b.Messages.Count));}finally{if(Directory.Exists(dir))Directory.Delete(dir,true);}});
  test("local guide does not confirm superseded fields and accepts consolidated corrections",()=>{var today=new DateOnly(2026,10,29);List<ConversationMessage> messages=[new(){Role="user",Content="明天在南京博物院参观，2小时"},new(){Role="user",Content="改成今天，只参观1小时"}];var reply=GuidedAgentClient.LocalReply(messages,today);if(reply.Ready){Equal(today,reply.Events.Single().Day);Equal(60,reply.Events.Single().Duration);}else Equal(true,reply.Missing.Count>0);messages.Add(new(){Role="user",Content="今天在南京博物院参观，1小时"});reply=GuidedAgentClient.LocalReply(messages,today);Equal(true,reply.Ready);Equal(today,reply.Events.Single().Day);Equal(60,reply.Events.Single().Duration);});
  test("editing an earlier user message retains old branch and forks exact prefix",()=>{dynamic c=New("GuidedConversation");dynamic first=c.AddUser("南京一日游");dynamic reply=New("GuidedReply");reply.Message="哪一天？";c.AddAssistant(reply);dynamic second=c.AddUser("明天");reply=New("GuidedReply");reply.Message="想去哪里？";c.AddAssistant(reply);string oldId=c.ActiveBranchId;c.ForkAt((string)second.Id,"后天");Equal(2,(int)c.Branches.Count);Equal(3,(int)c.Active.Messages.Count);Equal("后天",(string)c.Active.Messages[2].Content);Equal("明天",(string)c.Branches[0].Messages[2].Content);Equal(4,(int)c.Branches[0].Messages.Count);Reject(()=>c.ForkAt((string)c.Active.Messages[1].Id,"不能编辑助手"));});
  test("ready protocol requires actual dated activities and missing fields cannot silently pass",()=>{dynamic ready=Static("GuidedAgentClient","Parse",Ready);Equal(true,(bool)ready.Ready);Equal(1,(int)ready.Events.Count);Reject(()=>Static("GuidedAgentClient","Parse","{\"message\":\"好了\",\"ready\":true,\"events\":[]}"));Reject(()=>Static("GuidedAgentClient","Parse",Ready.Replace("2026-10-29","not-a-date")));});
  test("local guide remembers supplied date and only asks for missing activity details",()=>{dynamic c=New("GuidedConversation"),client=New("GuidedAgentClient",new HttpClient());c.AddUser("明天");dynamic first=client.ReplyAsync(new ServiceSettings{AgentProvider="LOCAL"},c.Active.Messages,CancellationToken.None).GetAwaiter().GetResult();Equal(false,(bool)first.Ready);Equal(false,((IEnumerable<string>)first.Missing).Contains("日期"));c.AddAssistant(first);c.AddUser("在南京博物院参观，2小时");dynamic ready=client.ReplyAsync(new ServiceSettings{AgentProvider="LOCAL"},c.Active.Messages,CancellationToken.None).GetAwaiter().GetResult();Equal(true,(bool)ready.Ready);Equal(120,(int)ready.Events[0].Duration);});
  test("model turn sends complete branch history and parses real structured response",()=>{int count=0;using var http=new HttpClient(new FixtureHandler(async req=>{count++;using var doc=JsonDocument.Parse(await req.Content!.ReadAsStringAsync());var msgs=doc.RootElement.GetProperty("messages");Equal(4,msgs.GetArrayLength());Equal("system",msgs[0].GetProperty("role").GetString());Equal("南京一日游",msgs[1].GetProperty("content").GetString());Equal("哪一天？",msgs[2].GetProperty("content").GetString());Equal("明天",msgs[3].GetProperty("content").GetString());return new(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(new{choices=new[]{new{message=new{content=Ready}}}}),Encoding.UTF8,"application/json")};}));dynamic c=New("GuidedConversation");c.AddUser("南京一日游");dynamic reply=New("GuidedReply");reply.Message="哪一天？";c.AddAssistant(reply);c.AddUser("明天");dynamic client=New("GuidedAgentClient",http);dynamic result=client.ReplyAsync(new ServiceSettings{AgentProvider="CUSTOM",Model="fixture",LlmEndpoint="http://localhost/v1"},c.Active.Messages,CancellationToken.None).GetAwaiter().GetResult();Equal(true,(bool)result.Ready);Equal(1,count);using var cancel=new CancellationTokenSource();cancel.Cancel();Reject(()=>client.ReplyAsync(new ServiceSettings{AgentProvider="LOCAL"},c.Active.Messages,cancel.Token).GetAwaiter().GetResult());});
  test("conversation branch history survives atomic local persistence",()=>{string d=Path.Combine(Path.GetTempPath(),"guided-history-"+Guid.NewGuid());try{dynamic c=New("GuidedConversation");c.AddUser("私人安排");dynamic store=New("ConversationStore",d);store.Save(c);dynamic read=store.Load();Equal("私人安排",(string)read.Active.Messages[0].Content);read.ForkAt((string)read.Active.Messages[0].Id,"修改后");store.Save(read);dynamic again=store.Load();Equal(2,(int)again.Branches.Count);Equal("私人安排",(string)again.Branches[0].Messages[0].Content);}finally{if(Directory.Exists(d))Directory.Delete(d,true);}});
  test("batch undo preserves unrelated insert and refuses modified generated activities",()=>{var before=State();var generated=Added(before);dynamic receipt=Static("GeneratedBatchService","Capture",before,generated,"branch");var later=ChangeService.Apply(generated,[new(){Activity=new(){Id="other",TableId="t",Title="另加",StartAt=new(2026,10,29,14,0,0),EndAt=new(2026,10,29,15,0,0)}}],generated.Revision);PlannerState undone=Static("GeneratedBatchService","Undo",later,receipt);Equal(1,undone.Activities.Count);Equal("other",undone.Activities[0].Id);var changed=later.Copy();changed.Activities.First(a=>a.Id=="generated").Note="手动编辑";Reject(()=>Static("GeneratedBatchService","Undo",changed,receipt));});
  test("batch undo blocks newly confirmed routes instead of deleting their dependencies",()=>{var before=State();var after=Added(before);dynamic receipt=Static("GeneratedBatchService","Capture",before,after,"branch");after.Plans.Add(new(){Id="p",PlanDate=new(2026,10,29)});after.Legs.Add(new(){PlanId="p",ToActivityId="generated"});Reject(()=>Static("GeneratedBatchService","Undo",after,receipt));});
  test("explicit overnight requests are planned on full dates and block following day overlap",()=>{var place=new Place{Id="p",Name="南京图书馆"};var late=new TripRequest{Day=new(2026,10,28),Title="夜间阅读",Location=place.Name,Start=1410,Duration=90};var plan=RepositoryPlanner.PlanAsync(new PlannerState(),[new(late,place)],(_,_,_,_,_)=>Task.FromResult(new TravelEstimate(0,"测试"))).GetAwaiter().GetResult();Equal(1410,plan.Rows.Single().Start);var s=State();s.Places.Add(place);s.Activities.Add(new(){TableId="t",Title="次日预约",PlaceId="p",StartAt=new(2026,10,29,0,30,0),EndAt=new(2026,10,29,2,0,0)});Reject(()=>RepositoryPlanner.PlanAsync(s,[new(late,place)],(_,_,_,_,_)=>Task.FromResult(new TravelEstimate(0,"测试"))).GetAwaiter().GetResult());});
  test("a new overnight request remains a constraint on the next generated day",()=>{var p=new Place{Id="p",Name="图书馆"};var items=new PreparedTrip[]{new(new(){Day=new(2026,10,28),Title="跨夜",Location=p.Name,Start=1380,Duration=660},p),new(new(){Day=new(2026,10,29),Title="次日",Location=p.Name,Duration=60},p)};var plan=RepositoryPlanner.PlanAsync(new PlannerState(),items,(_,_,_,_,_)=>Task.FromResult(new TravelEstimate(0,"测试"))).GetAwaiter().GetResult();Equal(600,plan.Rows[1].Start);});
  test("pending receipt recovers after SQLite write and scoped undo works after restart",()=>{string d=Path.Combine(Path.GetTempPath(),"guided-receipt-"+Guid.NewGuid());try{var before=State();var after=Added(before);dynamic receipt=Static("GeneratedBatchService","Capture",before,after,"branch");receipt.Status="PENDING";dynamic history=New("GuidedConversation");history.Batches.Add(receipt);dynamic store=New("ConversationStore",d);store.Save(history);var db=new SqliteStore(Path.Combine(d,"planner.db"));db.Save(after,0);dynamic loaded=store.Load();dynamic saved=loaded.Batches[0];Static("GeneratedBatchService","Reconcile",db.Load(),saved);Equal("APPLIED",(string)saved.Status);PlannerState undone=Static("GeneratedBatchService","Undo",db.Load(),saved);db.Save(undone,after.Revision);Equal(0,db.Load().Activities.Count);}finally{if(Directory.Exists(d))Directory.Delete(d,true);}});
  test("concurrent history writers cannot overwrite another branch silently",()=>{string d=Path.Combine(Path.GetTempPath(),"guided-race-"+Guid.NewGuid());try{dynamic store=New("ConversationStore",d);dynamic a=store.Load(),b=store.Load();a.AddUser("先保存");store.Save(a);b.AddUser("后覆盖");Reject(()=>store.Save(b));dynamic read=store.Load();Equal("先保存",(string)read.Active.Messages[0].Content);}finally{if(Directory.Exists(d))Directory.Delete(d,true);}});
  test("local guided request retains transport preferences and reminder details",()=>{dynamic c=New("GuidedConversation"),client=New("GuidedAgentClient",new HttpClient());c.AddUser("明天在南京博物院参观，2小时，公交，预算100元，提前20分钟提醒");dynamic r=client.ReplyAsync(new ServiceSettings{AgentProvider="LOCAL"},c.Active.Messages,CancellationToken.None).GetAwaiter().GetResult();Equal(true,(bool)r.Ready);Equal(true,((string)r.Events[0].Notes).Contains("预算100元"));Equal("公交",(string)r.Events[0].ModeIn);Equal(true,(bool)r.Events[0].ReminderEnabled);Equal(20,(int)r.Events[0].ReminderLeadMin);});
  test("undo intent reconciles a committed deletion after restart",()=>{var before=State();var after=Added(before);dynamic r=Static("GeneratedBatchService","Capture",before,after,"branch");r.Status="UNDO_PENDING";PlannerState undone=Static("GeneratedBatchService","Undo",after,r);Static("GeneratedBatchService","Reconcile",undone,r);Equal("UNDONE",(string)r.Status);});
  test("review commands retain explicit reminders alongside generated activities",()=>{var p=new Place{Name="南京博物院"};var req=new TripRequest{Day=new(2026,10,29),Title="参观",Location=p.Name,Duration=60,ReminderEnabled=true,ReminderLeadMin=35};var plan=new RepositoryPlan(0,[new(new(req,p),600,new(0,"无前序"),new(0,"无后续"),null,null)]);var commands=RepositoryPlanner.Commands(plan,"t");Equal(true,commands.Single().ReminderEnabled);Equal(35,commands.Single().ReminderLeadMin);});
  test("simultaneous conversation saves accept one writer and preserve its full branch",()=>{string d=Path.Combine(Path.GetTempPath(),"guided-simultaneous-"+Guid.NewGuid());try{var store=new ConversationStore(d);var copies=Enumerable.Range(0,8).Select(i=>{var c=store.Load();c.AddUser("writer-"+i);return c;}).ToArray();using var gate=new Barrier(8);int committed=0;var tasks=copies.Select(c=>Task.Run(()=>{gate.SignalAndWait();try{store.Save(c);Interlocked.Increment(ref committed);}catch(InvalidOperationException){}catch(IOException){}})).ToArray();Task.WaitAll(tasks);Equal(1,committed);Equal(1L,store.Load().Version);Equal(1,store.Load().Active.Messages.Count);}finally{if(Directory.Exists(d))Directory.Delete(d,true);}});
  test("malformed persisted assistant state is rejected without overwriting history",()=>{string d=Path.Combine(Path.GetTempPath(),"guided-malformed-"+Guid.NewGuid());Directory.CreateDirectory(d);try{string text="{\"version\":1,\"active_branch_id\":\"b\",\"branches\":[{\"id\":\"b\",\"messages\":[],\"reply\":{\"message\":\"草稿\",\"summary\":null,\"events\":null,\"missing\":null,\"ready\":true}}],\"batches\":[]}";File.WriteAllText(Path.Combine(d,"conversations.json"),text);Reject(()=>new ConversationStore(d).Load());Equal(text,File.ReadAllText(Path.Combine(d,"conversations.json")));}finally{Directory.Delete(d,true);}});
 }
}
